<script setup>
import {computed,ref} from 'vue';import {Store} from '../../store';import Icon from '../ui/EditionIcon.vue';
const search=ref('');
const logs=computed(()=>Store.state.activities.filter(a=>[a.action,a.details,a.user].join(' ').toLowerCase().includes(search.value.toLowerCase())).sort((a,b)=>String(b.date).localeCompare(String(a.date))));
function exportLog(){const rows=[['Date','Action','Details','User'],...logs.value.map(a=>[a.date,a.action,a.details,a.user])];const text=rows.map(row=>row.map(v=>'"'+String(v||'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='myfin-activity.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
<template><div v-if="Store.can('activityRead') && Store.state.online" class="ed-page"><header class="ed-page-head"><div><div class="ed-eyebrow">ADMINISTRATION / ACTIVITY</div><h1>A clear trail of the day.</h1><p>Changes, sales and store activity in one chronological view.</p></div><button class="ed-btn" @click="exportLog"><Icon name="download" />Export log</button></header><div class="ed-filters"><div class="ed-search"><Icon name="search" /><input v-model="search" class="ed-input" aria-label="Search activity" placeholder="Search activity or team member"></div><span class="ed-muted">{{ logs.length }} events</span></div><div v-for="log in logs" :key="log.id" class="ed-row"><span class="ed-avatar"><Icon :name="log.action?.toLowerCase().includes('sale')?'receipt':'clock'" /></span><div style="flex:1"><strong>{{ log.action||'Store activity' }}</strong><small>{{ log.details }}</small><small>{{ log.user }}</small></div><time class="ed-muted" style="font-size:11px;max-width:120px;text-align:right">{{ log.date?new Date(log.date).toLocaleString('en-MY'):'—' }}</time></div><div v-if="!logs.length" class="ed-empty"><Icon name="clock" /><h3>{{ search?'No matching events.':'A fresh page.' }}</h3><p>New store activity will appear here as your team works.</p></div></div><div v-else class="ed-notice">Connect with an authorized owner account to view this page.</div></template>
